import {toast} from 'sonner';
import {visibleCategories as categories,categoryImages,demoVenues,translated,currency,locale,istanbulDate,searchText,priceUnit,type Lang,type Venue,type AppState,type Booking,type Service,type Surface,type Feedback,type Review} from '@/lib/model';
import {translate} from '@/lib/i18n';
import {phases} from '@/lib/roadmap';
const icons:Record<string,typeof Store>={restaurant:Utensils,shopping:ShoppingBag,fun:Sparkles,nightlife:Music,rent:Car,beauty:Scissors,history:Landmark,nature:Trees,museum:Building2,pray:Church,clinic:Stethoscope,emergency:ShieldPlus,hotel:BedDouble};
const nav=[['home',Home],['people',Users],['support',LifeBuoy],['overview',LayoutDashboard],['venues',Store],['bookings',CalendarDays],['reviews',Star],['campaigns',Gift],['discover',Compass],['favorites',Heart],['roadmap',Flag],['settings',Settings],['help',LifeBuoy]] as const;
type Guide={surface:Surface;catalogQuery:string;setCatalogQuery:(v:string)=>void;catalogCategory:string;setCatalogCategory:(v:string)=>void;lang:Lang;t:(k:string)=>string;state:AppState;busy:boolean;city:string;view:string;setLang:(v:Lang)=>void;navigate:(v:string)=>void;edit:(v?:Venue)=>void;detail:(v:Venue)=>void;book:(v:Venue)=>void;mutate:(a:string,d:unknown,quiet?:boolean)=>Promise<Record<string,any>|undefined>;review:(b:Booking)=>void;reload:()=>Promise<void>};
const Context=createContext<Guide>(null!);function useGuide(){return useContext(Context)}
function Choice({value,onChange,options,label,className='',disabled=false}:{value:string;onChange:(v:string)=>void;options:{value:string;label:string}[];label:string;className?:string;disabled?:boolean}){return <Select value={value} onValueChange={onChange} disabled={disabled}><SelectTrigger className={'choice '+className} aria-label={label}><SelectValue/></SelectTrigger><SelectContent position="popper">{options.map(o=><SelectItem key={o.value} value={o.value}>{o.label}</SelectItem>)}</SelectContent></Select>}
function Photo({v,className=''}:{v:Venue;className?:string}){const{t}=useGuide();const[bad,setBad]=useState(false);useEffect(()=>setBad(false),[v.image]);return v.image&&!bad?<img className={className} src={v.image} alt={v.name} loading="lazy" onError={()=>setBad(true)}/>:<div className={'photo-fallback '+className}><MapPin/><span>{t('photoMissing')}</span></div>}
function Badge({status}:{status:string}){const{t}=useGuide();return <span className={'badge '+status}>{t(status==='open'?'ticketOpen':status)}</span>}
function Empty({title,text,action}:{title:string;text?:string;action?:React.ReactNode}){const{t}=useGuide();return <div className="empty-state"><Compass size={32}/><h3>{t(title)}</h3>{text&&<p>{t(text)}</p>}{action}</div>}
function LanguagePicker(){const{lang,setLang,t}=useGuide();return <Choice className="language-choice" value={lang} onChange={v=>setLang(v as Lang)} label={t('language')} options={[{value:'ru',label:'RU · Русский'},{value:'tr',label:'TR · Türkçe'},{value:'en',label:'EN · English'}]}/>}
function navigation(surface:Surface){
 const allowed=surface==='admin'?['overview','venues','bookings','reviews','people','support','campaigns','roadmap','settings']:surface==='partner'?['overview','venues','bookings','reviews','campaigns','discover','settings','help']:['home','discover','favorites','bookings','campaigns','settings','help'];
 return nav.filter(([key])=>allowed.includes(key));
}
function SideNavigation(){
 const{t,view,navigate,state,surface}=useGuide();const{setOpenMobile}=useSidebar();
 return <Sidebar className="app-sidebar"><SidebarHeader><button className="brand" onClick={()=>navigate('overview')}><span className="brand-symbol"><MapPin/></span>City Guide</button><div className="workspace-label">{t(surface==='admin'?'adminArea':'partnerPanel')}<span>İSTANBUL</span></div></SidebarHeader><SidebarContent><SidebarGroup><SidebarGroupLabel>{t('workspace')}</SidebarGroupLabel><SidebarMenu>{navigation(surface).map(([key,Icon])=><SidebarMenuItem key={key}><SidebarMenuButton isActive={view===key} onClick={()=>{navigate(key);setOpenMobile(false)}} className="side-link"><Icon/><span>{t(key)}</span>{key==='venues'&&<small>{state.venues.filter(v=>!v.isDemo&&v.status!=='archived').length}</small>}</SidebarMenuButton></SidebarMenuItem>)}</SidebarMenu></SidebarGroup></SidebarContent><SidebarFooter><button className="identity" onClick={()=>navigate('settings')}><span className="avatar">{state.user?.name?.charAt(0)||'N'}</span><span><b>{state.user?.name||'City Guide'}</b><small>{t(surface==='admin'?'adminArea':'partner')}</small></span><Settings size={16}/></button></SidebarFooter></Sidebar>;
}
export default function CityGuide({surface='tourist'}:{surface?:Surface}){
 const[lang,setLanguage]=useState<Lang>('ru');const[view,setView]=useState(surface==='tourist'?'home':'overview');const[city,setCity]=useState('İstanbul');
 const[catalogQuery,setCatalogQuery]=useState('');const[catalogCategory,setCatalogCategory]=useState('all');
 const[state,setState]=useState<AppState>({user:null,venues:demoVenues,bookings:[],favorites:[],reviews:[],feedback:[],mode:'preview'});
 const[busy,setBusy]=useState(false);const[loading,setLoading]=useState(true);const[loadError,setLoadError]=useState('');const[editing,setEditing]=useState<Venue|null|undefined>(undefined);
 const[selected,setSelected]=useState<Venue|null>(null);const[booking,setBooking]=useState<Venue|null>(null);const[reviewing,setReviewing]=useState<Booking|null>(null);
 const languageRef=useRef(false);const t=(key:string)=>translate(key,lang);
 async function reload(){setLoading(true);try{const r=await fetch('/api/state?surface='+surface,{cache:'no-store'});const d=await r.json() as AppState&{error?:string};if(!r.ok)throw new Error(d.error||'failed');setState(d);setLoadError('');if(!languageRef.current&&d.user?.language){setLanguage(d.user.language);languageRef.current=true}}catch(e){setLoadError(e instanceof Error?e.message:'failed')}finally{setLoading(false)}}
 useEffect(()=>{const saved=localStorage.getItem('city-guide-language');if(saved&&['ru','tr','en'].includes(saved)){setLanguage(saved as Lang);languageRef.current=true}const handle=()=>{const v=location.hash.slice(1);if(navigation(surface).some(n=>n[0]===v)||v==='discover'&&surface==='admin')setView(v)};handle();window.addEventListener('hashchange',handle);void reload();if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});return()=>window.removeEventListener('hashchange',handle)},[surface]);
 useEffect(()=>{document.documentElement.lang=lang},[lang]);
 function setLang(v:Lang){setLanguage(v);languageRef.current=true;localStorage.setItem('city-guide-language',v)}
 function navigate(v:string){if(v==='favorites'){setCatalogQuery('');setCatalogCategory('all')}if(v==='home'&&surface!=='tourist')v='overview';setView(v);location.hash=v;window.scrollTo({top:0,behavior:'smooth'})}
 async function mutate(action:string,data:unknown,quiet=false){if(busy)return;setBusy(true);try{const r=await fetch('/api/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,data,surface})});const d=await r.json() as {error?:string;state:AppState;result?:Record<string,unknown>};if(!r.ok)throw new Error(d.error||'failed');setState(d.state);setLoadError('');if(!quiet)toast.success(t('saved'));return d.result||{ok:true}}catch(e){toast.error(t(e instanceof Error?e.message:'failed'));return undefined}finally{setBusy(false)}}
 const context:Guide={surface,catalogQuery,setCatalogQuery,catalogCategory,setCatalogCategory,lang,t,state,busy,city,view,setLang,navigate,edit:v=>setEditing(v||null),detail:v=>setSelected(v),book:v=>setBooking(v),mutate,review:b=>setReviewing(b),reload};
 useEffect(()=>{const ctx=(document as any).modelContext;if(!ctx?.registerTool)return;const controller=new AbortController();const register=(tool:any)=>Promise.resolve(ctx.registerTool(tool,{signal:controller.signal})).catch(()=>{});
 register({name:'search_city_guide_places',description:'Search visible City Guide places without modifying records.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async(input:any)=>{if(typeof input?.query!=='string')throw new Error('query must be a string');return state.venues.filter(v=>searchText(v.name+' '+v.city+' '+v.district).includes(searchText(input.query))).map(v=>({id:v.id,name:v.name,city:v.city,status:v.status,isDemo:v.isDemo}))}});
 register({name:'navigate_city_guide',description:'Open a City Guide section without modifying records.',inputSchema:{type:'object',properties:{section:{type:'string',enum:navigation(surface).map(n=>n[0])}},required:['section'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:async(input:any)=>{if(!navigation(surface).some(n=>n[0]===input?.section))throw new Error('Unknown section');navigate(input.section);return {section:input.section}}});return()=>controller.abort()},[state.venues,surface]);
 const cities=[...new Set(['İstanbul','Ankara','İzmir','Antalya','Adana','Mersin',...state.venues.map(v=>v.city)])];
 const notice=<>{loadError&&<div className="connection-notice"><span>{t(loadError==='signin_required'?'previewNote':loadError)}</span>{loadError==='signin_required'?<a className="button small" target="_top" href={'/signin-with-chatgpt?return_to=/'+surface}>{t('signin')}</a>:<button className="button small" onClick={()=>void reload()}><RefreshCw size={15}/>{t('retry')}</button>}</div>}{loading&&<div className="loading-line" role="status"><Loader2 className="spin" size={15}/>{t('loading')}</div>}</>;
 const pages=<>{view==='overview'&&(surface==='admin'?<AdminOverview/>:<Overview/>)}{view==='venues'&&<Places/>}{view==='discover'&&<Discover/>}{view==='favorites'&&<Discover favoritesOnly/>}{view==='bookings'&&(surface==='tourist'?<MyTrips/>:<Bookings/>)}{view==='reviews'&&<ReviewManagement/>}{view==='campaigns'&&<Offers/>}{view==='people'&&surface==='admin'&&<People/>}{view==='support'&&surface==='admin'&&<SupportDesk/>}{view==='roadmap'&&<Roadmap/>}{view==='settings'&&<SettingsPage/>}{view==='help'&&(surface==='tourist'?<TouristHelp/>:<Help/>)}</>;
 const cityPicker=<Choice className="city-choice" value={city} onChange={setCity} label={t('city')} options={[{value:'all',label:t('allCities')},...cities.map(c=>({value:c,label:c}))]}/>;
 return <Context.Provider value={context}>{surface==='tourist'?<div className="tourist-app"><header className="tourist-header"><div className="tourist-header-top"><a className="tourist-brand" href="/tourist">City Guide</a><LanguagePicker/></div><div className="tourist-header-bottom"><div><MapPin size={18}/>{cityPicker}</div></div></header><main className="tourist-content">{notice}{view==='home'?<TouristHome/>:pages}</main><TouristNavigation/></div>:<SidebarProvider><SideNavigation/><div className="app-main"><header className="topbar"><div className="breadcrumb"><SidebarTrigger aria-label={t('workspace')}/><b>{t(view)}</b></div><div className="top-actions">{cityPicker}<LanguagePicker/></div></header><main className={'content '+(view==='discover'?'discovery-content':'')}>{notice}{pages}</main><footer className="page-footer"><span>City Guide © 2026</span></footer></div></SidebarProvider>}
 {editing!==undefined&&surface!=='tourist'&&<VenueEditor value={editing} onClose={()=>setEditing(undefined)}/>}
 <VenueDetails value={selected?state.venues.find(v=>v.id===selected.id)||selected:null} onClose={()=>setSelected(null)}/>
 {booking&&<BookingForm venue={booking} onClose={()=>setBooking(null)}/>}{reviewing&&<ReviewForm booking={reviewing} onClose={()=>setReviewing(null)}/>}<Toaster richColors position="bottom-right" theme="light" closeButton/></Context.Provider>;
}
function PageTitle({title,text,action}:{title:string;text?:string;action?:React.ReactNode}){const{t,surface}=useGuide();return <div className="page-title"><div>{surface!=='tourist'&&<p className="eyebrow">CITY GUIDE</p>}<h1>{t(title)}</h1>{text&&<p className="subtitle">{t(text)}</p>}</div>{action}</div>}
function Overview(){const{state,city,t,edit,navigate,lang}=useGuide();const venues=state.venues.filter(v=>(city==='all'||v.city===city)&&v.status!=='archived');const real=venues.filter(v=>!v.isDemo);const awaiting=state.bookings.filter(b=>b.status==='pending').length;return <><PageTitle title="overviewTitle" text="overviewText" action={<button className="button primary" onClick={()=>edit()}><Plus size={18}/>{t('addVenue')}</button>}/><div className="stats-grid">{[[Store,venues.filter(v=>v.status==='published').length,'placesTotal','İstanbul'],[Building2,real.length,'realPartners',''],[CalendarDays,awaiting,'pendingBookings',t('testReservations')],[Languages,'03','languages','Русский · Türkçe · English']].map(([Icon,n,label,caption])=>{const I=Icon as typeof Store;return <div className="stat-card" key={String(label)}><div className="stat-top"><span>{t(String(label))}</span><I size={18}/></div><strong>{String(n).padStart(2,'0')}</strong>{caption&&<small>{String(caption)}</small>}</div>})}</div><div className="overview-columns"><div><section className="panel catalog-panel"><div className="section-title"><div><span className="tiny-line"/><h2>{t('recentPlaces')}</h2></div><button className="text-button" onClick={()=>navigate('venues')}>{t('viewAll')}</button></div><div className="overview-cards">{venues.slice(0,3).map(v=><PlaceCard key={v.id} v={v} compact/>)}{venues.length===0&&<Empty title="noVenue" text="cityFuture"/>}</div><p className="subtle-note">{t('demoNote')}</p></section><section className="panel requests-panel"><div className="section-title"><h2>{t('latestBookings')}</h2><button className="text-button" onClick={()=>navigate('bookings')}>{t('viewAll')}</button></div>{state.bookings.length?<BookingRows items={state.bookings.slice(0,4)}/>:<Empty title="noBookings" text="noBookingsText" action={<button className="button" onClick={()=>navigate('discover')}>{t('openCatalog')}</button>}/>}</section></div><aside className="overview-aside"><div className="launch-card"><span className="launch-icon"><Flag size={22}/></span><p className="eyebrow">{t('basicLaunch')}</p><h2>{t('launchChecklist')}</h2><div className="checklist">{[['checkBrand',true,'settings'],['checkDemo',true,'discover'],['checkPlace',real.length>0,'venues'],['checkBooking',state.bookings.length>0,'bookings']].map(([label,done,dest])=><button key={String(label)} onClick={()=>navigate(String(dest))}><span className={'check-circle '+(done?'done':'')}>{done?<Check size={13}/>:null}</span>{t(String(label))}</button>)}</div><button className="button primary" onClick={()=>navigate('roadmap')}>{t('roadmap')}</button></div><div className="city-preview"><img src="/images/istanbul.webp" alt="İstanbul"/><div><span>İSTANBUL</span><h2>{t('guidePreview')}</h2><button className="button" onClick={()=>navigate('discover')}><Compass size={16}/>{t('showCatalog')}</button></div></div></aside></div></>}
function PlaceCard({v,compact=false}:{v:Venue;compact?:boolean}){const{t,lang,state,detail,mutate,busy}=useGuide();const favorite=state.favorites.includes(v.id);const reviews=state.reviews.filter(r=>r.venueId===v.id&&r.status!=='hidden');const rating=reviews.length?(reviews.reduce((s,r)=>s+r.rating,0)/reviews.length).toFixed(1):null;return <article className={'place-card '+(compact?'compact':'')}><button className="place-image" onClick={()=>detail(v)} aria-label={v.name}><Photo v={v}/>{v.isDemo&&<span className="image-badge">{t('demo')}</span>}{v.discount>0&&<span className="discount-tag">−{v.discount}%</span>}</button><button className={'favorite '+(favorite?'selected':'')} disabled={busy} aria-label={t(favorite?'removeFavorite':'addFavorite')} onClick={()=>void mutate('favorite',{id:v.id,value:!favorite},true)}><Heart size={17} fill={favorite?'currentColor':'none'}/></button><div className="place-copy"><p className="place-category">{t(v.category)}{rating&&<span><Star size={13} fill="currentColor"/>{rating}</span>}</p><button onClick={()=>detail(v)} className="place-name">{v.name}</button><p className="place-location"><MapPin size={13}/>{v.district||v.city}{v.district&&' · '+v.city}</p>{!compact&&<div className="card-bottom"><span>{v.price>0?currency(v.price,v.currency,lang):t('requestPrice')}{v.price>0&&<small> / {t(priceUnit(v.bookingType))}</small>}</span><button className="text-button" onClick={()=>detail(v)}>{t('details')}</button></div>}</div></article>}
function Places(){const{state,t,city,edit,detail}=useGuide();const[q,setQ]=useState('');const[category,setCategory]=useState('all');const[status,setStatus]=useState('all');const[realOnly,setRealOnly]=useState(false);const items=state.venues.filter(v=>(city==='all'||v.city===city)&&(category==='all'||v.category===category)&&(status==='all'||v.status===status)&&(!realOnly||!v.isDemo)&&searchText(v.name+' '+v.district).includes(searchText(q)));return <><PageTitle title="catalogTitle" text="yourPlacesHint" action={<button className="button primary" onClick={()=>edit()}><Plus size={18}/>{t('addVenue')}</button>}/><div className="filters"><div className="search-input"><Search size={18}/><Input placeholder={t('search')} value={q} onChange={e=>setQ(e.target.value)} aria-label={t('search')}/></div><Choice label={t('category')} value={category} onChange={setCategory} options={[{value:'all',label:t('allCategories')},...categories.map(c=>({value:c,label:t(c)}))]}/><Choice label={t('status')} value={status} onChange={setStatus} options={['all','draft','pending','published','archived'].map(c=>({value:c,label:t(c==='all'?'allStatuses':c)}))}/><label className="switch-label"><Switch checked={realOnly} onCheckedChange={setRealOnly}/>{t('realOnly')}</label></div><div className="panel table-panel"><Table><TableHeader><TableRow><TableHead>{t('name')}</TableHead><TableHead>{t('category')}</TableHead><TableHead>{t('city')}</TableHead><TableHead>{t('status')}</TableHead><TableHead className="table-right">{t('edit')}</TableHead></TableRow></TableHeader><TableBody>{items.map(v=><TableRow key={v.id}><TableCell><button className="table-place" onClick={()=>detail(v)}><Photo v={v}/><span><b>{v.name}</b><small>{v.district} {v.isDemo&&'· '+t('demo')}</small></span></button></TableCell><TableCell>{t(v.category)}</TableCell><TableCell>{v.city}</TableCell><TableCell><Badge status={v.status}/></TableCell><TableCell className="table-right">{(state.user?.role==='admin'||v.ownerId===state.user?.id)&&<button className="icon-button" aria-label={t('edit')+' '+v.name} onClick={()=>edit(v)}><Pencil size={17}/></button>}</TableCell></TableRow>)}</TableBody></Table>{items.length===0&&<Empty title="noResults" action={<button className="button" onClick={()=>{setQ('');setCategory('all');setStatus('all');setRealOnly(false)}}>{t('resetFilters')}</button>}/>}</div></>}
function Discover({favoritesOnly=false}:{favoritesOnly?:boolean}){const{state,t,lang,city,detail,navigate,catalogQuery:q,setCatalogQuery:setQ,catalogCategory:category,setCatalogCategory:setCategory}=useGuide();const[map,setMap]=useState(false);const[mapPlace,setMapPlace]=useState<Venue|null>(null);const[alcohol,setAlcohol]=useState(false);const[exchange,setExchange]=useState(false);const list=state.venues.filter(v=>v.status==='published'&&(city==='all'||v.city===city)&&(category==='all'||v.category===category)&&(!favoritesOnly||state.favorites.includes(v.id))&&(!alcohol||v.alcohol)&&searchText(v.name+' '+v.district+' '+v.subcategory+' '+translated(v.description,lang)).includes(searchText(q)));return <><div className={'discover-hero '+(favoritesOnly?'small-hero':'')}><div><p className="eyebrow">{city==='all'?'TÜRKİYE':city.toLocaleUpperCase('tr')}</p><h1>{t(favoritesOnly?'favorites':'discoverTitle')}</h1><p>{t(favoritesOnly?'favoriteHint':'discoverText')}</p><div className="hero-actions"><button className="button" onClick={()=>setExchange(true)}><Coins size={16}/>{t('exchange')}</button><button className="button" onClick={()=>{if(list.length)detail(list[Math.floor(Math.random()*list.length)]);else toast.info(t('noResults'))}}><Shuffle size={16}/>{t('random')}</button></div></div>{!favoritesOnly&&<img src="/images/istanbul.webp" alt="İstanbul"/>}</div><div className="catalog-controls"><div className="search-input"><Search size={18}/><Input value={q} onChange={e=>setQ(e.target.value)} placeholder={'Ask Me · '+t('search')} aria-label={t('search')}/></div><button className={'button '+(map?'active':'')} onClick={()=>setMap(!map)}>{map?<LayoutGrid size={17}/>:<Map size={17}/>} {t(map?'list':'map')}</button></div><div className="category-strip"><button className={category==='all'?'active':''} onClick={()=>setCategory('all')}><Compass size={21}/><span>{t('all')}</span></button>{categories.map(c=>{const I=icons[c];return <button key={c} className={category===c?'active':''} onClick={()=>{setCategory(c);setAlcohol(false)}}><I size={21}/><span>{t(c)}</span></button>})}</div><div className="catalog-count"><span>{t(category==='all'?'placesTotal':category)} <b>{list.length}</b></span>{category==='restaurant'&&<label className="switch-label"><Switch checked={alcohol} onCheckedChange={setAlcohol}/>{t('alcohol')}</label>}<span className="subtle-note">{t('demoFilter')}</span></div>{map&&list.length>0?<div className="map-layout"><div className="map-places">{list.map(v=><button key={v.id} className={'map-place '+((mapPlace?.id||list[0]?.id)===v.id?'active':'')} onClick={()=>setMapPlace(v)}><Photo v={v}/><span><b>{v.name}</b><small>{v.district}</small></span></button>)}</div><div className="map-frame"><MapEmbed venue={mapPlace&&list.some(v=>v.id===mapPlace.id)?mapPlace:list[0]}/><button className="button primary" onClick={()=>detail(mapPlace&&list.some(v=>v.id===mapPlace.id)?mapPlace:list[0])}>{t('details')}</button></div></div>:<div className="places-grid">{list.map(v=><PlaceCard key={v.id} v={v}/>)}</div>}{!list.length&&<Empty title={favoritesOnly?'noFavorites':'noResults'} text={favoritesOnly?'favoriteHint':'cityFuture'} action={<button className="button" onClick={()=>{setQ('');setCategory('all');setAlcohol(false);if(favoritesOnly)navigate('discover')}}>{t(favoritesOnly?'openCatalog':'resetFilters')}</button>}/>}<p className="subtle-note">{t('demoNote')}</p><Exchange open={exchange} close={()=>setExchange(false)}/></>}
function MapEmbed({venue:v}:{venue:Venue}){return <iframe title={v.name+' · OpenStreetMap'} src={`https://www.openstreetmap.org/export/embed.html?bbox=${v.lng-.018}%2C${v.lat-.011}%2C${v.lng+.018}%2C${v.lat+.011}&layer=mapnik&marker=${v.lat}%2C${v.lng}`} loading="lazy" referrerPolicy="strict-origin-when-cross-origin"/>}
function VenueDetails({value:v,onClose}:{value:Venue|null;onClose:()=>void}){const{t,lang,state,book,edit,surface}=useGuide();if(!v)return null;const reviews=state.reviews.filter(r=>r.venueId===v.id&&r.status!=='hidden');return <Sheet open={!!v} onOpenChange={open=>!open&&onClose()}><SheetContent className="detail-sheet"><SheetHeader><SheetTitle className="brand">City Guide</SheetTitle><SheetDescription>{t(v.category)} · {v.city}</SheetDescription></SheetHeader><div className="detail-body"><Photo v={v} className="detail-photo"/><div className="detail-heading"><div><h2>{v.name}</h2><p><MapPin size={14}/>{v.district} · {v.city}</p></div>{v.isDemo&&<Badge status="demo"/>}</div>{v.gallery.length>1&&<div className="gallery">{v.gallery.map((img,i)=><img src={img} key={i} alt={v.name+' '+(i+1)}/>)}</div>}<Tabs defaultValue="about"><TabsList className="detail-tabs"><TabsTrigger value="about">{t('about')}</TabsTrigger><TabsTrigger value="menu">{t('menu')}</TabsTrigger><TabsTrigger value="location">{t('location')}</TabsTrigger><TabsTrigger value="reviews">{t('reviews')}</TabsTrigger></TabsList><TabsContent value="about"><p className="detail-description">{translated(v.description,lang)}</p><div className="info-row"><Clock size={18}/><div><b>{t('hours')}</b><p>{t('daily')} · {v.open}–{v.close}</p></div></div>{v.alcohol&&<div className="info-row"><CheckCircle2 size={18}/>{t('alcohol')}</div>}{v.phone&&<div className="info-row"><a className="text-button" href={'tel:'+v.phone}>{v.phone}</a></div>}{v.website&&<a className="text-button" href={v.website} target="_blank" rel="noreferrer">{t('website')}</a>}</TabsContent><TabsContent value="menu">{v.services.length?<div className="service-list">{v.services.map(s=><div key={s.id} className="service-row">{s.image&&<img src={s.image} alt={translated(s.name,lang)}/>}<span>{translated(s.name,lang)}</span><b>{currency(s.price,v.currency,lang)}</b></div>)}</div>:<Empty title="emptyServices"/>}<p className="subtle-note">{t('menuOnly')}</p></TabsContent><TabsContent value="location"><p className="detail-address"><MapPin size={20}/>{v.address}</p><div className="detail-map"><MapEmbed venue={v}/></div><a className="button" href={`https://www.google.com/maps/dir/?api=1&destination=${v.lat},${v.lng}`} target="_blank" rel="noreferrer"><Navigation size={16}/>{t('directions')}</a></TabsContent><TabsContent value="reviews">{reviews.length?reviews.map(r=><article className="review" key={r.id}><div><span className="avatar">{r.author.charAt(0)}</span><b>{r.author}</b><Stars value={r.rating}/></div><small>{new Date(r.createdAt).toLocaleDateString(locale[lang])} · {r.isDemo?t('test'):''}</small><p>{r.text}</p>{r.reply&&<div className="review-reply"><b>{t('businessReply')}</b><p>{r.reply}</p></div>}</article>):<Empty title="noReviews" text="reviewHint"/>}</TabsContent></Tabs>{v.isDemo&&<p className="demo-disclaimer">{t('demoNote')}</p>}</div><div className="detail-bottom"><div><strong>{v.price?currency(v.price,v.currency,lang):t('requestPrice')}</strong>{v.price>0&&<small>{t(priceUnit(v.bookingType))}</small>}</div>{v.bookingType!=='none'&&v.status==='published'?<button className="button primary" onClick={()=>book(v)}>{t('reserve')}</button>:<a className="button primary" href={`https://www.google.com/maps/dir/?api=1&destination=${v.lat},${v.lng}`} target="_blank" rel="noreferrer">{t('directions')}</a>}{surface!=='tourist'&&state.user&&(state.user.role==='admin'||v.ownerId===state.user.id)&&<button className="icon-button" aria-label={t('edit')} onClick={()=>edit(v)}><Pencil size={19}/></button>}</div></SheetContent></Sheet>}
function BookingRows({items}:{items:Booking[]}){const{t,lang,state,mutate,busy,review,surface}=useGuide();return <Table><TableHeader><TableRow><TableHead>{t('customer')}</TableHead><TableHead>{t('venues')}</TableHead><TableHead>{t('dateRange')}</TableHead><TableHead>{t('status')}</TableHead><TableHead>{t('view')}</TableHead></TableRow></TableHeader><TableBody>{items.map(b=>{const v=state.venues.find(v=>v.id===b.venueId);const owner=surface!=='tourist'&&(state.user?.role==='admin'||v?.ownerId===state.user?.id);return <TableRow key={b.id}><TableCell><b>{b.name}</b><small className="block-meta">{b.isDemo?t('test')+' · ':''}{b.id.slice(0,8)}</small></TableCell><TableCell>{b.venueName}<small className="block-meta">{b.guests} · {t('guests').toLocaleLowerCase(locale[lang])}</small></TableCell><TableCell>{new Date(b.date+'T12:00:00').toLocaleDateString(locale[lang])}<small className="block-meta">{b.endDate!==b.date?b.endDate:b.time}</small></TableCell><TableCell><Badge status={b.status}/></TableCell><TableCell><div className="row-actions">{b.status==='pending'&&owner&&<button disabled={busy} className="button small primary" onClick={()=>void mutate('bookingStatus',{id:b.id,status:'confirmed'})}>{t('confirm')}</button>}{b.status==='confirmed'&&owner&&<button disabled={busy} className="button small" onClick={()=>void mutate('bookingStatus',{id:b.id,status:'completed'})}>{t('complete')}</button>}{['pending','confirmed'].includes(b.status)&&<button className="icon-button" disabled={busy} aria-label={t('cancelBooking')} onClick={()=>void mutate('bookingStatus',{id:b.id,status:'cancelled'})}><X size={16}/></button>}{b.status==='completed'&&b.userId===state.user?.id&&!state.reviews.some(r=>r.bookingId===b.id)&&<button className="button small" onClick={()=>review(b)}><Star size={14}/>{t('writeReview')}</button>}</div></TableCell></TableRow>})}</TableBody></Table>}
function Bookings(){const{state,t,city,navigate}=useGuide();const[status,setStatus]=useState('all');const[period,setPeriod]=useState('all');const visible=state.bookings.filter(b=>(status==='all'||b.status===status)&&(city==='all'||state.venues.find(v=>v.id===b.venueId)?.city===city)&&(period==='all'||Date.now()-Date.parse(b.createdAt)<Number(period)*86400000));return <><PageTitle title="bookings" text="testReservations" action={<button className="button" onClick={()=>navigate('discover')}><Plus size={17}/>{t('reserve')}</button>}/><div className="filters"><Choice value={status} onChange={setStatus} label={t('status')} options={['all','pending','confirmed','completed','cancelled'].map(v=>({value:v,label:t(v==='all'?'allStatuses':v)}))}/><Choice value={period} onChange={setPeriod} label={t('filterPeriod')} options={[{value:'all',label:t('allData')},{value:'7',label:t('week')},{value:'30',label:t('month')},{value:'90',label:t('quarter')},{value:'365',label:t('year')}]}/><span className="result-count">{visible.length}</span></div><section className="panel table-panel">{visible.length?<BookingRows items={visible}/>:<Empty title="noBookings" text="noBookingsText" action={<button className="button" onClick={()=>navigate('discover')}>{t('openCatalog')}</button>}/>}</section></>}
function Stars({value,onChange}:{value:number;onChange?:(n:number)=>void}){const{t}=useGuide();return <div className={'stars '+(onChange?'editable':'')}>{[1,2,3,4,5].map(n=>onChange?<button type="button" key={n} aria-label={t('rating')+' '+n} aria-pressed={value===n} onClick={()=>onChange(n)}><Star fill={n<=value?'currentColor':'none'}/></button>:<Star key={n} fill={n<=value?'currentColor':'none'} size={16}/>)}</div>}
function Reviews(){const{state,t,lang}=useGuide();return <><PageTitle title="reviewsTitle" text="reviewHint"/>{state.reviews.length?<div className="review-grid">{state.reviews.map(r=><article className="panel review" key={r.id}><div><span className="avatar">{r.author.charAt(0)}</span><b>{r.author}</b><Stars value={r.rating}/></div><small>{state.venues.find(v=>v.id===r.venueId)?.name} · {new Date(r.createdAt).toLocaleDateString(locale[lang])}{r.isDemo&&' · '+t('test')}</small><p>{r.text}</p>{r.reply&&<div className="review-reply"><b>{t('businessReply')}</b><p>{r.reply}</p></div>}</article>)}</div>:<section className="panel"><Empty title="noReviews" text="noLiveReviews"/></section>}</>}
function Offers(){const{state,t,city,surface}=useGuide();const list=state.venues.filter(v=>v.status==='published'&&v.discount>0&&(city==='all'||city===v.city));return <><PageTitle title="offersTitle" text="offersText"/><div className="offer-banner"><Gift size={38}/><div><p>City Guide</p><h2>{t('campaigns')}</h2><span>{t(surface==='tourist'?'offersText':'setDiscount')}</span></div></div>{list.length?<div className="places-grid">{list.map(v=><PlaceCard key={v.id} v={v}/>)}</div>:<Empty title="noOffers" text={surface==='tourist'?'offersText':'setDiscount'}/>}<p className="subtle-note">{t('demoNote')}</p></>}
function Roadmap(){const{t,lang}=useGuide();return <><PageTitle title="planTitle" text="planSubtitle" action={<a className="button" href="/City_Guide_Plan_RU.md" download><Download size={17}/>{t('downloadPlan')}</a>}/><div className="roadmap-list">{phases.map(p=><section className={'panel roadmap-phase '+p.status} key={p.number}><span className="phase-number">{p.number}</span><div><Badge status={p.status}/><h2>{translated(p.title,lang)}</h2><p>{translated(p.items,lang)}</p><div className="acceptance"><CheckCircle2 size={17}/>{translated(p.acceptance,lang)}</div></div></section>)}</div></>}
function SettingsPage(){const{state,t,lang,setLang,mutate,busy}=useGuide();const[p,setP]=useState({name:state.user?.name||'',phone:state.user?.phone||'',language:lang,homeAddress:state.user?.homeAddress||''});const[rate,setRate]=useState(false);useEffect(()=>{if(state.user)setP({name:state.user.name,phone:state.user.phone,language:lang,homeAddress:state.user.homeAddress})},[state.user?.id]);async function save(e:React.FormEvent){e.preventDefault();const ok=await mutate('profile',{...p,language:lang});if(ok)setLang(lang)}return <><PageTitle title="settings"/><div className="settings-grid"><form className="panel form-grid" onSubmit={save}><h2 className="full">{t('profile')}</h2><Field label={t('fullName')}><Input required minLength={2} value={p.name} onChange={e=>setP({...p,name:e.target.value})}/></Field><Field label={t('email')}><Input value={state.user?.email||''} readOnly/></Field><Field label={t('phone')}><Input type="tel" value={p.phone} onChange={e=>setP({...p,phone:e.target.value})}/></Field><Field label={t('language')}><LanguagePicker/></Field><Field label={t('homeAddress')} className="full"><Input value={p.homeAddress} onChange={e=>setP({...p,homeAddress:e.target.value})}/></Field><div className="form-actions full"><button type="submit" disabled={busy} className="button primary">{t(busy?'saving':'save')}</button>{p.homeAddress&&<a className="button" target="_blank" rel="noreferrer" href={'https://www.google.com/maps/dir/?api=1&destination='+encodeURIComponent(p.homeAddress)}><Navigation size={16}/>{t('goHome')}</a>}</div></form><div className="settings-side"><section className="panel"><h2>{t('export')}</h2><p>{t('exportHint')}</p><button className="button" onClick={()=>{const b=new Blob([JSON.stringify({exportedAt:new Date().toISOString(),profile:state.user,venues:state.venues,bookings:state.bookings,reviews:state.reviews,favorites:state.favorites,feedback:state.feedback||[]},null,2)],{type:'application/json'});const url=URL.createObjectURL(b);const a=document.createElement('a');a.href=url;a.download='city-guide-export-'+istanbulDate()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}}><Download size={16}/>{t('export')}</button></section><section className="panel"><h2>{t('appRating')}</h2><button className="button" onClick={()=>setRate(true)}><Star size={16}/>{t('appRating')}</button></section><a className="button" target="_top" href="/signout-with-chatgpt?return_to=/"><LogOut size={16}/>{t('logout')}</a></div></div><div className="future-grid"><section className="panel"><CreditCard/><h3>{t('paymentSoon')}</h3><p>{t('payNotice')}</p><Badge status="planned"/></section><section className="panel"><Gift/><h3>{t('points')}</h3><p>{t('pointsSoon')}</p><Badge status="planned"/></section></div>{rate&&<FeedbackForm onClose={()=>setRate(false)} kind="app"/>}</>}
function Help(){const{t}=useGuide();const[open,setOpen]=useState(false);return <><PageTitle title="help"/><section className="panel help-panel"><LifeBuoy size={36}/><h2>{t('supportText')}</h2><button className="button primary" onClick={()=>setOpen(true)}><Send size={17}/>{t('submit')}</button></section><Roadmap/>{open&&<FeedbackForm kind="help" onClose={()=>setOpen(false)}/>}</>}
function Field({label,children,className=''}:{label:string;children:React.ReactNode;className?:string}){return <label className={'field '+className}><span>{label}</span>{children}</label>}
function blankVenue():Venue{return {id:'',name:'',category:'restaurant',subcategory:'',city:'İstanbul',district:'',address:'',lat:41.025,lng:28.975,description:{ru:'',tr:'',en:''},image:'',gallery:[],phone:'',website:'',open:'09:00',close:'22:00',price:0,currency:'TRY',bookingType:'table',capacity:10,alcohol:false,status:'draft',isDemo:false,ownerId:'',updatedAt:'',version:0,discount:0,services:[]}}
function VenueEditor({value,onClose}:{value:Venue|null;onClose:()=>void}){const{t,lang,mutate,busy,state}=useGuide();const[v,setV]=useState<Venue>(()=>value?structuredClone(value):blankVenue());const[uploading,setUploading]=useState(false);const[tab,setTab]=useState('basic');const set=(key:keyof Venue,val:unknown)=>setV(prev=>({...prev,[key]:val}));async function upload(e:React.ChangeEvent<HTMLInputElement>,gallery=false){const file=e.target.files?.[0];if(!file)return;setUploading(true);try{const form=new FormData();form.append('file',file);const r=await fetch('/api/upload',{method:'POST',body:form});const d=await r.json() as {error?:string;url:string};if(!r.ok)throw new Error(d.error);setV(prev=>({...prev,image:gallery?prev.image:d.url,gallery:gallery?[...prev.gallery,d.url].slice(0,12):[d.url,...prev.gallery.filter(x=>x!==prev.image)].slice(0,12)}))}catch(e){toast.error(t(e instanceof Error?e.message:'invalid_image'))}finally{setUploading(false);e.target.value=''}}async function save(e:React.FormEvent){e.preventDefault();const payload={...v,id:v.id||undefined};const r=await mutate('saveVenue',payload);if(r)onClose()}return <Dialog open onOpenChange={o=>!o&&onClose()}><DialogContent className="editor-dialog"><DialogHeader><DialogTitle>{t(value?'editVenue':'addVenue')}</DialogTitle><DialogDescription>{t('baseInfo')}</DialogDescription></DialogHeader><form onSubmit={save} onInvalidCapture={e=>{const section=(e.target as HTMLElement).closest('[data-slot="tabs-content"]');if(section?.getAttribute('data-state')==='inactive'){const id=section.id;setTab(id.endsWith('basic')?'basic':id.endsWith('booking')?'booking':'services')}}}><Tabs value={tab} onValueChange={setTab}><TabsList className="editor-tabs"><TabsTrigger value="basic">{t('baseInfo')}</TabsTrigger><TabsTrigger value="booking">{t('operation')}</TabsTrigger><TabsTrigger value="services">{t('menu')}</TabsTrigger></TabsList><div className="editor-scroll"><TabsContent value="basic" forceMount hidden={tab!=='basic'}><div className="photo-editor">{v.image?<img src={v.image} alt={v.name}/>:<div className="upload-preview"><ImagePlus size={32}/></div>}<div><label className="button"><Upload size={16}/>{t('uploadPhoto')}<input type="file" hidden accept="image/jpeg,image/png,image/webp" disabled={uploading} onChange={e=>void upload(e)}/></label><p>{uploading?t('saving'):t('photoHint')}</p></div></div><div className="form-grid"><Field label={t('name')} className="full"><Input required minLength={2} maxLength={160} value={v.name} onChange={e=>set('name',e.target.value)}/></Field><Field label={t('category')}><Choice label={t('category')} value={v.category} onChange={val=>setV(prev=>({...prev,category:val as Venue['category'],bookingType:({restaurant:'table',rent:'rental',beauty:'appointment',clinic:'appointment',hotel:'stay',fun:'ticket',museum:'ticket'} as Record<string,Venue['bookingType']>)[val]||'none'}))} options={categories.map(c=>({value:c,label:t(c)}))}/></Field><Field label={t('subcategory')}><Input value={v.subcategory} onChange={e=>set('subcategory',e.target.value)}/></Field><Field label={t('city')}><Input required value={v.city} onChange={e=>set('city',e.target.value)}/></Field><Field label={t('district')}><Input value={v.district} onChange={e=>set('district',e.target.value)}/></Field><Field label={t('address')} className="full"><Input value={v.address} onChange={e=>set('address',e.target.value)}/></Field><Field label={t('latitude')}><Input type="number" step="any" min={-90} max={90} value={v.lat} onChange={e=>set('lat',Number(e.target.value))}/></Field><Field label={t('longitude')}><Input type="number" step="any" min={-180} max={180} value={v.lng} onChange={e=>set('lng',Number(e.target.value))}/></Field><Field label={t('phone')}><Input type="tel" value={v.phone} onChange={e=>set('phone',e.target.value)}/></Field><Field label={t('website')}><Input type="url" placeholder="https://" value={v.website} onChange={e=>set('website',e.target.value)}/></Field>{(['ru','tr','en'] as Lang[]).map(l=><Field key={l} className="full" label={t('description')+' · '+({ru:'Русский',tr:'Türkçe',en:'English'}[l])}><Textarea maxLength={4000} rows={3} value={v.description[l]} onChange={e=>set('description',{...v.description,[l]:e.target.value})}/></Field>)}<div className="full"><label className="button"><Plus size={16}/>{t('galleryAdd')}<input hidden type="file" accept="image/jpeg,image/png,image/webp" disabled={uploading||v.gallery.length>=12} onChange={e=>void upload(e,true)}/></label><div className="gallery edit-gallery">{v.gallery.map((url,i)=><div key={url}><img src={url} alt={t('photo')+' '+(i+1)}/><button className="icon-button" type="button" aria-label={t('remove')} onClick={()=>set('gallery',v.gallery.filter(x=>x!==url))}><X size={14}/></button></div>)}</div></div></div></TabsContent><TabsContent value="booking" forceMount hidden={tab!=='booking'}><div className="form-grid"><Field label={t('opens')}><Input required type="time" value={v.open} onChange={e=>set('open',e.target.value)}/></Field><Field label={t('closes')}><Input required type="time" value={v.close} onChange={e=>set('close',e.target.value)}/></Field><Field label={t('bookingType')} className="full"><Choice value={v.bookingType} label={t('bookingType')} onChange={val=>set('bookingType',val)} options={['table','rental','appointment','ticket','stay','none'].map(c=>({value:c,label:t(c)}))}/></Field><Field label={t('price')}><Input type="number" min={0} max={1000000} step="0.01" value={v.price} onChange={e=>set('price',Number(e.target.value))}/></Field><Field label={t('currency')}><Choice value={v.currency} onChange={val=>set('currency',val)} label={t('currency')} options={['TRY','USD','EUR'].map(c=>({value:c,label:c}))}/></Field><Field label={t('capacity')}><Input type="number" required min={1} max={10000} value={v.capacity} onChange={e=>set('capacity',Number(e.target.value))}/></Field><Field label={t('discount')}><Input type="number" min={0} max={90} value={v.discount} onChange={e=>set('discount',Number(e.target.value))}/></Field><label className="switch-label full"><Switch checked={v.alcohol} onCheckedChange={val=>set('alcohol',val)}/>{t('alcohol')}</label></div></TabsContent><TabsContent value="services" forceMount hidden={tab!=='services'}><div className="service-editor">{v.services.map((s,i)=><div className="service-edit-row" key={s.id}><div className="form-grid">{(['ru','tr','en'] as Lang[]).map(l=><Field key={l} className="full" label={t('serviceName')+' · '+l.toUpperCase()}><Input value={s.name[l]} onChange={e=>set('services',v.services.map((x,n)=>n===i?{...x,name:{...x.name,[l]:e.target.value}}:x))}/></Field>)}<Field label={t('price')}><Input type="number" min={0} step="0.01" value={s.price} onChange={e=>set('services',v.services.map((x,n)=>n===i?{...x,price:Number(e.target.value)}:x))}/></Field><Field label={t('duration')}><Input type="number" min={1} max={1440} value={s.duration} onChange={e=>set('services',v.services.map((x,n)=>n===i?{...x,duration:Number(e.target.value)}:x))}/></Field></div><button className="text-button danger" type="button" onClick={()=>set('services',v.services.filter((_,n)=>n!==i))}>{t('deleteService')}</button></div>)}<button type="button" className="button" onClick={()=>set('services',[...v.services,{id:crypto.randomUUID(),name:{ru:'',tr:'',en:''},price:0,duration:60,image:v.image}])}><Plus size={16}/>{t('addService')}</button></div></TabsContent></div></Tabs><div className="editor-footer"><Choice value={v.status} onChange={val=>set('status',val)} label={t('status')} options={(state.user?.role==='admin'?['draft','pending','published','archived']:['draft','pending','archived']).map(c=>({value:c,label:t(c)}))}/><div><button type="button" className="button" onClick={onClose}>{t('cancel')}</button><button type="submit" disabled={busy||uploading} className="button primary">{busy&&<Loader2 size={16} className="spin"/>}{t(busy?'saving':'save')}</button></div></div></form></DialogContent></Dialog>}
function BookingForm({venue:v,onClose}:{venue:Venue;onClose:()=>void}){const{t,lang,state,mutate,busy,navigate}=useGuide();const period=['rental','stay'].includes(v.bookingType);const[requestId]=useState(()=>crypto.randomUUID());const[p,setP]=useState({name:state.user?.name||'',phone:state.user?.phone||'',date:istanbulDate(new Date(Date.now()+86400000)),time:'12:00',endDate:'',guests:1,payment:'onsite',note:''});const[success,setSuccess]=useState(false);const days=period&&p.endDate?Math.max(0,(Date.parse(p.endDate)-Date.parse(p.date))/86400000):1;const total=v.price*(period?days:v.bookingType==='ticket'?p.guests:1)*(1-v.discount/100);async function save(e:React.FormEvent){e.preventDefault();const r=await mutate('book',{...p,id:requestId,venueId:v.id},true);if(r){setSuccess(true);toast.success(t('requestSent'))}}return <Dialog open onOpenChange={o=>!o&&onClose()}><DialogContent className="booking-dialog"><DialogHeader><DialogTitle>{success?t('requestSent'):t('reserve')}</DialogTitle><DialogDescription>{t('demoBooking')}</DialogDescription></DialogHeader>{success?<div className="booking-success"><CheckCircle2 size={54}/><h2>{v.name}</h2><p>{p.date} · {p.time}</p><p>{t('bookingRef')}: {requestId.slice(0,8)}</p><p>{t('requestNotConfirmed')}</p><button className="button primary" onClick={()=>{onClose();navigate('bookings')}}>{t('bookings')}</button></div>:<form onSubmit={save}><div className="booking-venue"><Photo v={v}/><div><b>{v.name}</b><small>{v.district} · {t(v.bookingType)}</small></div></div><div className="form-grid"><Field label={t('fullName')}><Input required minLength={2} value={p.name} onChange={e=>setP({...p,name:e.target.value})}/></Field><Field label={t('phone')}><Input type="tel" value={p.phone} onChange={e=>setP({...p,phone:e.target.value})}/></Field><Field label={t('date')}><Input type="date" required min={istanbulDate()} value={p.date} onChange={e=>setP({...p,date:e.target.value})}/></Field><Field label={t('time')}><Input type="time" required value={p.time} onChange={e=>setP({...p,time:e.target.value})}/></Field>{period&&<Field label={t('endDate')}><Input type="date" required min={p.date} value={p.endDate} onChange={e=>setP({...p,endDate:e.target.value})}/></Field>}<Field label={t('guests')}><Input type="number" required min={1} max={100} value={p.guests} onChange={e=>setP({...p,guests:Number(e.target.value)})}/></Field><Field label={t('note')} className="full"><Textarea value={p.note} maxLength={1000} onChange={e=>setP({...p,note:e.target.value})}/></Field><Field label={t('payment')} className="full"><Choice value={p.payment} onChange={val=>setP({...p,payment:val})} label={t('payment')} options={[{value:'onsite',label:t('onsite')},{value:'demo',label:t('demoPay')}]}/></Field></div>{p.payment==='demo'&&<p className="demo-disclaimer">{t('payNotice')}</p>}<div className="booking-total"><span>{t('total')}{v.discount>0&&' · −'+v.discount+'%'}</span><strong>{v.price>0?currency(total,v.currency,lang):t('requestPrice')}</strong></div><button disabled={busy} className="button primary full-button" type="submit">{t(busy?'saving':'sendRequest')}</button></form>}</DialogContent></Dialog>}
function ReviewForm({booking:b,onClose}:{booking:Booking;onClose:()=>void}){const{t,mutate,busy}=useGuide();const[rating,setRating]=useState(0);const[text,setText]=useState('');return <Dialog open onOpenChange={o=>!o&&onClose()}><DialogContent><DialogHeader><DialogTitle>{t('writeReview')}</DialogTitle><DialogDescription>{b.venueName}</DialogDescription></DialogHeader><form className="feedback-form" onSubmit={async e=>{e.preventDefault();if(!rating)return;const r=await mutate('review',{bookingId:b.id,rating,text},true);if(r){toast.success(t('thanks'));onClose()}}}><Stars value={rating} onChange={setRating}/><Textarea required minLength={3} maxLength={2000} value={text} onChange={e=>setText(e.target.value)} placeholder={t('comment')} aria-label={t('comment')}/><button className="button primary" disabled={busy||rating===0}>{t('submit')}</button></form></DialogContent></Dialog>}
function FeedbackForm({kind,onClose}:{kind:'app'|'help';onClose:()=>void}){const{t,mutate,busy}=useGuide();const[rating,setRating]=useState(0);const[text,setText]=useState('');return <Dialog open onOpenChange={o=>!o&&onClose()}><DialogContent><DialogHeader><DialogTitle>{t(kind==='app'?'appRating':'help')}</DialogTitle><DialogDescription>{t('supportText')}</DialogDescription></DialogHeader><form className="feedback-form" onSubmit={async e=>{e.preventDefault();const r=await mutate('feedback',{kind,rating,text},true);if(r){toast.success(t(kind==='app'?'thanks':'helpSaved'));onClose()}}}>{kind==='app'&&<Stars value={rating} onChange={setRating}/>}<Textarea required minLength={3} maxLength={2000} value={text} onChange={e=>setText(e.target.value)} aria-label={t('supportText')}/><button disabled={busy||(kind==='app'&&!rating)} className="button primary">{t('submit')}</button></form></DialogContent></Dialog>}

function formatDate(value:string,lang:Lang,withTime=false){
 return new Date(value.length===10?value+'T12:00:00+03:00':value).toLocaleString(locale[lang],{timeZone:'Europe/Istanbul',day:'numeric',month:'short',year:'numeric',...(withTime?{hour:'2-digit',minute:'2-digit'}:{})});
}
function AdminOverview(){
 const{state,city,t,edit,detail,mutate,busy,navigate}=useGuide();
 const places=state.venues.filter(v=>city==='all'||v.city===city);
 const pending=places.filter(v=>v.status==='pending');
 const bookings=state.bookings.filter(b=>b.status==='pending'&&(city==='all'||places.some(v=>v.id===b.venueId)));
 const tickets=(state.feedback||[]).filter(f=>f.status!=='resolved');
 const stats:[[typeof Store,number,string],...Array<[typeof Store,number,string]>]=[
  [Store,places.filter(v=>v.status==='published').length,'placesTotal'],[ShieldCheck,pending.length,'pendingPlaces'],
  [CalendarDays,bookings.length,'pendingBookings'],[MessageSquare,tickets.length,'openTickets']
 ];
 return <><PageTitle title="adminDashboard" text="adminDashboardText" action={<button className="button primary" onClick={()=>edit()}><Plus size={18}/>{t('addVenue')}</button>}/>
  <div className="stats-grid">{stats.map(([Icon,count,key])=><div className="stat-card" key={key}><div className="stat-top"><span>{t(key)}</span><Icon size={20}/></div><strong>{count}</strong><small>{key==='openTickets'?t('allCities'):city==='all'?t('allCities'):city}</small></div>)}</div>
  <div className="admin-columns"><div className="admin-main-column">
   <section className="panel"><div className="section-title"><div><h2>{t('approvals')}</h2><p className="subtitle">{t('approvalText')}</p></div><button className="text-button" onClick={()=>navigate('venues')}>{t('viewAll')}</button></div>
    {pending.length?<div className="approval-list">{pending.slice(0,6).map(v=><article className="approval-item" key={v.id}><button className="approval-photo" onClick={()=>detail(v)} aria-label={v.name}><Photo v={v}/></button><div className="approval-copy"><h3>{v.name}</h3><p>{t(v.category)} · {v.district||v.city}</p><small>{t('listingOwner')}: {state.users?.find(u=>u.id===v.ownerId)?.name||t('demo')}</small><div className="row-actions"><button disabled={busy} className="button primary small" onClick={()=>void mutate('venueStatus',{id:v.id,status:'published',version:v.version})}><Check size={16}/>{t('approve')}</button><button className="button small" onClick={()=>edit(v)}>{t('edit')}</button><button disabled={busy} className="text-button" onClick={()=>void mutate('venueStatus',{id:v.id,status:'draft',version:v.version})}>{t('returnDraft')}</button></div></div></article>)}</div>:<Empty title="noApprovals"/>}
   </section>
   <section className="panel"><div className="section-title"><h2>{t('pendingBookings')}</h2><button className="text-button" onClick={()=>navigate('bookings')}>{t('viewAll')}</button></div>{bookings.length?<BookingRows items={bookings.slice(0,5)}/>:<Empty title="noBookings" text="noBookingsText"/>}</section>
  </div><aside className="admin-aside">
   <section className="panel"><h2>{t('moderation')}</h2><p>{t('moderationHint')}</p><div className="admin-shortcuts">{[['people',Users,'managePeople'],['reviews',Star,'reviewManagement'],['support',LifeBuoy,'support']].map(([key,Icon,label])=>{const I=Icon as typeof Store;return <button className="button" key={String(key)} onClick={()=>navigate(String(key))}><I size={18}/>{t(String(label))}<ChevronRight size={16}/></button>})}</div></section>
   <section className="panel partner-count"><Users size={24}/><strong>{state.users?.filter(u=>u.role==='partner').length||0}</strong><p>{t('registeredPartners')}</p><button className="text-button" onClick={()=>navigate('people')}>{t('managePeople')}</button></section>
   <a className="city-preview admin-tourist-link" href="/tourist"><img src="/images/istanbul.webp" alt="İstanbul"/><div><span>CITY GUIDE</span><h2>{t('viewAsTourist')}</h2><span className="button"><Compass size={16}/>{t('openCatalog')}</span></div></a>
  </aside></div>
 </>;
}
function People(){
 const{t,state,mutate,busy}=useGuide();const[q,setQ]=useState('');const[role,setRole]=useState('all');
 const list=(state.users||[]).filter(u=>(role==='all'||u.role===role)&&searchText(u.name+' '+u.email).includes(searchText(q)));
 return <><PageTitle title="managePeople" text="peopleText"/><div className="filters"><div className="search-input"><Search size={18}/><Input value={q} onChange={e=>setQ(e.target.value)} aria-label={t('search')} placeholder={t('search')}/></div><Choice label={t('role')} value={role} onChange={setRole} options={['all','admin','partner','tourist'].map(v=>({value:v,label:t(v==='all'?'allRoles':v==='admin'?'adminArea':v)}))}/><span className="result-count">{list.length}</span></div>
  <section className="panel table-panel">{list.length?<Table><TableHeader><TableRow><TableHead>{t('name')}</TableHead><TableHead>{t('email')}</TableHead><TableHead>{t('venues')}</TableHead><TableHead>{t('role')}</TableHead></TableRow></TableHeader><TableBody>{list.map(u=><TableRow key={u.id}><TableCell><div className="person-cell"><span className="avatar">{u.name.charAt(0)}</span><b>{u.name}</b></div></TableCell><TableCell>{u.email}</TableCell><TableCell>{state.venues.filter(v=>v.ownerId===u.id&&!v.isDemo).length}</TableCell><TableCell>{u.role==='admin'?<span className="owner-role"><ShieldCheck size={16}/>{t('ownerLocked')}</span>:<Choice label={t('role')+' · '+u.name} value={u.role} disabled={busy} onChange={v=>void mutate('userRole',{id:u.id,role:v,expectedRole:u.role})} options={['tourist','partner'].map(v=>({value:v,label:t(v)}))}/>}</TableCell></TableRow>)}</TableBody></Table>:<Empty title="noPeople"/>}</section>
 </>;
}
function ReviewManagement(){
 const{t,state,lang,mutate,busy}=useGuide();const[status,setStatus]=useState('all');const[editing,setEditing]=useState<Review|null>(null);const[reply,setReply]=useState('');
 const admin=state.user?.role==='admin',list=state.reviews.filter(r=>status==='all'||(r.status||'published')===status);
 return <><PageTitle title="reviewManagement" text="reviewManagementText"/><div className="filters"><Choice label={t('status')} value={status} onChange={setStatus} options={['all','published','hidden'].map(v=>({value:v,label:t(v==='all'?'allStatuses':v)}))}/><span className="result-count">{list.length}</span></div>
  {list.length?<div className="review-grid">{list.map(r=>{const venue=state.venues.find(v=>v.id===r.venueId),mayReply=admin||state.user?.role==='partner'&&venue?.ownerId===state.user.id;return <article className="panel managed-review" key={r.id}><div className="review-author"><span className="avatar">{r.author.charAt(0)}</span><div><h3>{r.author}</h3><small>{venue?.name} · {formatDate(r.createdAt,lang)}</small></div><Badge status={r.status||'published'}/></div><Stars value={r.rating}/>{r.isDemo&&<span className="test-label">{t('test')}</span>}<p className="user-text">{r.text}</p>{r.reply&&<div className="review-reply"><b>{t('businessReply')}</b><p>{r.reply}</p></div>}<div className="row-actions">{mayReply&&<button className="button small" onClick={()=>{setEditing(r);setReply(r.reply||'')}}><MessageSquare size={16}/>{t(r.reply?'editReply':'reply')}</button>}{admin&&<button disabled={busy} className="text-button" onClick={()=>void mutate('moderateReview',{id:r.id,version:r.version||1,status:r.status==='hidden'?'published':'hidden'})}>{t(r.status==='hidden'?'restoreReview':'hideReview')}</button>}</div></article>})}</div>:<section className="panel"><Empty title="noReviews" text="noLiveReviews"/></section>}
  {admin&&<p className="subtle-note">{t('reviewHiddenNote')}</p>}
  <Dialog open={!!editing} onOpenChange={o=>!o&&setEditing(null)}><DialogContent><DialogHeader><DialogTitle>{t('businessReply')}</DialogTitle><DialogDescription>{editing?.author}</DialogDescription></DialogHeader><form className="feedback-form" onSubmit={async e=>{e.preventDefault();if(editing&&await mutate('reviewReply',{id:editing.id,version:editing.version||1,reply}))setEditing(null)}}><Textarea value={reply} onChange={e=>setReply(e.target.value)} maxLength={2000} aria-label={t('businessReply')} placeholder={t('replyPlaceholder')}/><button className="button primary" disabled={busy}>{t('save')}</button></form></DialogContent></Dialog>
 </>;
}
function TicketCard({ticket,onEdit}:{ticket:Feedback;onEdit?:(ticket:Feedback)=>void}){
 const{t,lang}=useGuide();return <article className="panel ticket-card"><div className="ticket-heading"><div><h3>{t(ticket.kind==='app'?'ticketApp':'ticketHelp')}</h3><small>{ticket.author} · {formatDate(ticket.createdAt,lang,true)}</small></div><Badge status={ticket.status}/></div>{ticket.kind==='app'&&<Stars value={ticket.rating}/>}<p className="user-text">{ticket.text}</p>{ticket.reply&&<div className="review-reply"><b>{t('supportReply')}</b><p>{ticket.reply}</p></div>}{onEdit&&<button className="button small" onClick={()=>onEdit(ticket)}><MessageSquare size={16}/>{t('updateTicket')}</button>}</article>;
}
function SupportDesk(){
 const{state,t,busy,mutate}=useGuide();const[status,setStatus]=useState('all');const[kind,setKind]=useState('all');const[editing,setEditing]=useState<Feedback|null>(null);const[reply,setReply]=useState('');const[nextStatus,setNextStatus]=useState('in_progress');
 const list=(state.feedback||[]).filter(f=>(status==='all'||f.status===status)&&(kind==='all'||f.kind===kind));
 return <><PageTitle title="support" text="supportDeskText"/><div className="filters"><Choice label={t('status')} value={status} onChange={setStatus} options={['all','open','in_progress','resolved'].map(v=>({value:v,label:t(v==='all'?'allStatuses':v==='open'?'ticketOpen':v)}))}/><Choice label={t('support')} value={kind} onChange={setKind} options={['all','help','app'].map(v=>({value:v,label:t(v==='all'?'allKinds':v==='help'?'ticketHelp':'ticketApp')}))}/><span className="result-count">{list.length}</span></div>
  {list.length?<div className="ticket-grid">{list.map(ticket=><TicketCard key={ticket.id} ticket={ticket} onEdit={f=>{setEditing(f);setReply(f.reply);setNextStatus(f.status==='open'?'in_progress':f.status)}}/>)}</div>:<section className="panel"><Empty title="noTickets"/></section>}
  <Dialog open={!!editing} onOpenChange={o=>!o&&setEditing(null)}><DialogContent><DialogHeader><DialogTitle>{t('updateTicket')}</DialogTitle><DialogDescription>{editing?.author}</DialogDescription></DialogHeader><form className="feedback-form" onSubmit={async e=>{e.preventDefault();if(editing&&await mutate('feedbackStatus',{id:editing.id,version:editing.version,reply,status:nextStatus}))setEditing(null)}}><p className="user-text">{editing?.text}</p><Field label={t('status')}><Choice label={t('status')} value={nextStatus} onChange={setNextStatus} options={['open','in_progress','resolved'].map(v=>({value:v,label:t(v==='open'?'ticketOpen':v)}))}/></Field><Field label={t('supportReply')}><Textarea value={reply} onChange={e=>setReply(e.target.value)} maxLength={2000} placeholder={t('replyPlaceholder')}/></Field><button className="button primary" disabled={busy}>{t('save')}</button></form></DialogContent></Dialog>
 </>;
}
function WeatherCard(){
 const{city,state,t,lang}=useGuide();const[forecast,setForecast]=useState<{temperature:number;symbol:string;time:string}|null>(null);const[failed,setFailed]=useState(false);const[retry,setRetry]=useState(0);
 const name=city==='all'?'İstanbul':city;
 const locations:Record<string,[number,number]>={'İstanbul':[41.01,28.97],'Ankara':[39.93,32.86],'İzmir':[38.42,27.14],'Antalya':[36.89,30.71],'Adana':[37,35.32],'Mersin':[36.81,34.64]};
 const place=state.venues.find(v=>v.city===name);const coords=locations[name]||(place?[place.lat,place.lng]:null);const lat=coords?.[0],lon=coords?.[1];
 useEffect(()=>{setForecast(null);setFailed(false);if(lat===undefined||lon===undefined){setFailed(true);return}const controller=new AbortController();fetch('/api/weather?lat='+lat+'&lon='+lon,{signal:AbortSignal.any([controller.signal,AbortSignal.timeout(12000)])}).then(async r=>{if(!r.ok)throw new Error('unavailable');const data=await r.json() as {temperature:number;symbol:string;time:string};if(!Number.isFinite(data.temperature)||typeof data.symbol!=='string'||!Number.isFinite(Date.parse(data.time)))throw new Error('unavailable');return data}).then(setForecast).catch(()=>{if(!controller.signal.aborted)setFailed(true)});return()=>controller.abort()},[lat,lon,retry]);
 const rain=forecast?.symbol.match(/rain|snow|sleet|thunder/),cloud=forecast?.symbol.includes('cloud'),Icon=rain?CloudRain:cloud?Cloud:Sun;
 return <section className="weather-card" aria-label={t('forecastTitle')}><img src="/images/istanbul.webp" alt=""/><div className="weather-content"><div><p>{t('forecastTitle')}</p><h2>{name}</h2>{forecast&&<small>{t('forecastTime')} {new Date(forecast.time).toLocaleTimeString(locale[lang],{timeZone:'Europe/Istanbul',hour:'2-digit',minute:'2-digit'})} · {t(rain?'weatherRain':cloud?'weatherCloud':'weatherClear')}</small>}</div><div className="weather-value">{forecast?<><Icon size={48}/><strong>{Math.round(forecast.temperature)}°</strong></>:failed?<button className="button small" onClick={()=>setRetry(r=>r+1)}><RefreshCw size={16}/>{t('retry')}</button>:<Loader2 size={26} className="spin"/>}</div></div>{failed&&<p className="weather-error">{t('forecast_unavailable')}</p>}<p className="weather-attribution"><a href="https://www.met.no/en" target="_blank" rel="noreferrer">MET Norway</a> · <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noreferrer">CC BY 4.0</a></p></section>;
}
function TouristHome(){
 const{t,state,city,detail,navigate,catalogQuery,setCatalogQuery,setCatalogCategory}=useGuide();const[exchange,setExchange]=useState(false);
 const places=state.venues.filter(v=>v.status==='published'&&(city==='all'||v.city===city)),offer=places.find(v=>v.discount>0);
 function browse(category='all'){setCatalogCategory(category);if(category!=='all')setCatalogQuery('');navigate('discover')}
 return <><div className="traveler-greeting"><div><p>{t('travelerGreeting')}, {state.user?.name||t('tourist')}!</p><h1>{t('exploreCity')}</h1></div><button className="button small" onClick={()=>setExchange(true)}><Coins size={18}/>{t('exchange')}</button></div>
  <WeatherCard/><p className="traveler-intro">{t('travelerIntro')}</p>
  <form className="tourist-search" onSubmit={e=>{e.preventDefault();browse()}}><Search size={22}/><Input value={catalogQuery} onChange={e=>setCatalogQuery(e.target.value)} placeholder={t('findPlace')} aria-label={t('findPlace')}/><button className="button primary" aria-label={t('search')}><ChevronRight size={22}/></button></form>
  <section className="home-categories"><div className="section-title"><h2>{t('exploreCategories')}</h2><button className="text-button" onClick={()=>{setCatalogQuery('');browse()}}>{t('showAllPlaces')}</button></div><div className="category-photo-grid">{categories.map(category=>{const I=icons[category],place=places.find(v=>v.category===category),image=categoryImages[category];return <button key={category} onClick={()=>browse(category)}>{image?<img src={image} alt="" loading="lazy"/>:place?<Photo v={place}/>:<div className="category-placeholder"><I size={36}/></div>}<span>{t(category)}</span></button>})}</div></section>
  {offer&&<button className="home-offer" onClick={()=>detail(offer)}><Photo v={offer}/><div><Gift size={24}/><p>{t('offersShort')}</p><h2>{offer.name}</h2><strong>−{offer.discount}%</strong>{offer.isDemo&&<small>{t('demo')}</small>}</div><ChevronRight size={26}/></button>}
  <section className="home-featured"><div className="section-title"><h2>{t('featuredPlaces')}</h2><button className="text-button" onClick={()=>{setCatalogQuery('');browse()}}>{t('viewAll')}</button></div>{places.length?<div className="places-grid">{places.slice(0,3).map(v=><PlaceCard key={v.id} v={v}/>)}</div>:<Empty title="noVenue" text="cityFuture"/>}</section>
  <div className="home-actions"><button className="button" onClick={()=>navigate('campaigns')}><Gift size={18}/>{t('campaigns')}</button><button className="button" onClick={()=>places.length?detail(places[Math.floor(Math.random()*places.length)]):toast.info(t('noResults'))}><Shuffle size={18}/>{t('random')}</button><button className="button" onClick={()=>navigate('help')}><LifeBuoy size={18}/>{t('help')}</button></div>
  {places.some(v=>v.isDemo)&&<p className="subtle-note">{t('demoNote')}</p>}<Exchange open={exchange} close={()=>setExchange(false)}/>
 </>;
}
function TouristNavigation(){
 const{t,view,navigate}=useGuide();const links:[string,typeof Home,string,string][]=[['home',Home,'navHome','home'],['favorites',Heart,'navFavorites','favorites'],['bookings',CalendarDays,'navBookings','myTrips'],['settings',UserRound,'navProfile','travelerProfile'],['discover',MapPin,'navDiscover','discover']];
 return <nav className="tourist-navigation" aria-label={t('guide')}>{links.map(([key,Icon,label,fullLabel])=><button key={key} aria-label={t(fullLabel)} title={t(fullLabel)} className={view===key?'active':''} aria-current={view===key?'page':undefined} onClick={()=>navigate(key)}><Icon size={20}/><span>{t(label)}</span></button>)}</nav>;
}
function MyTrips(){
 const{state,t,lang,busy,mutate,review,navigate}=useGuide();const[status,setStatus]=useState('all');const[period,setPeriod]=useState('all');const[cancelling,setCancelling]=useState<Booking|null>(null);
 const list=state.bookings.filter(b=>b.userId===state.user?.id&&(status==='all'||b.status===status)&&(period==='all'||Date.now()-Date.parse(b.createdAt)<Number(period)*86400000));
 return <><PageTitle title="myTrips" text="myTripsText" action={<button className="button primary" onClick={()=>navigate('discover')}><Plus size={18}/>{t('reserve')}</button>}/><div className="filters"><Choice label={t('status')} value={status} onChange={setStatus} options={['all','pending','confirmed','completed','cancelled'].map(v=>({value:v,label:t(v==='all'?'allStatuses':v)}))}/><Choice label={t('filterPeriod')} value={period} onChange={setPeriod} options={[['all','allData'],['7','week'],['30','month'],['90','quarter'],['365','year']].map(([value,key])=>({value,label:t(key)}))}/><span className="result-count">{list.length}</span></div>
  {list.length?<div className="trip-list">{list.map(b=>{const place=state.venues.find(v=>v.id===b.venueId),ownReview=state.reviews.find(r=>r.bookingId===b.id);return <article className="panel trip-card" key={b.id}>{place&&<Photo v={place} className="trip-photo"/>}<div className="trip-copy"><div className="trip-heading"><div><h2>{b.venueName}</h2><small>{t('bookingRef')}: {b.id.slice(0,8)}{b.isDemo&&' · '+t('test')}</small></div><Badge status={b.status}/></div><div className="trip-facts"><span><CalendarDays size={18}/>{formatDate(b.date,lang)}{b.endDate!==b.date?' — '+formatDate(b.endDate,lang):' · '+b.time}</span><span><Users size={18}/>{b.guests} · {t('guests')}</span><span><Coins size={18}/>{t('tripTotal')}: {b.total>0?currency(b.total,b.currency,lang):t('requestPrice')}</span></div>{b.note&&<p className="user-text">{b.note}</p>}{b.status==='pending'&&<p className="subtle-note">{t('requestNotConfirmed')}</p>}<div className="row-actions">{['pending','confirmed'].includes(b.status)&&<button disabled={busy} className="button small" onClick={()=>setCancelling(b)}>{t('cancelBooking')}</button>}{b.status==='completed'&&!ownReview&&<button className="button primary small" onClick={()=>review(b)}><Star size={16}/>{t('writeReview')}</button>}</div>{ownReview&&<div className="trip-review"><b>{t('yourReview')}</b><Stars value={ownReview.rating}/><p>{ownReview.text}</p>{ownReview.status==='hidden'&&<Badge status="hidden"/>}{ownReview.reply&&<div className="review-reply"><b>{t('businessReply')}</b><p>{ownReview.reply}</p></div>}</div>}</div></article>})}</div>:<section className="panel"><Empty title="noTrips" text="noBookingsText" action={<button className="button primary" onClick={()=>navigate('discover')}>{t('openCatalog')}</button>}/></section>}
  <Dialog open={!!cancelling} onOpenChange={o=>!o&&setCancelling(null)}><DialogContent><DialogHeader><DialogTitle>{t('cancelTripTitle')}</DialogTitle><DialogDescription>{t('cancelTripText')}</DialogDescription></DialogHeader><p>{cancelling?.venueName}</p><div className="row-actions"><button className="button" onClick={()=>setCancelling(null)}>{t('keepBooking')}</button><button disabled={busy} className="button primary" onClick={async()=>{if(cancelling&&await mutate('bookingStatus',{id:cancelling.id,status:'cancelled'}))setCancelling(null)}}>{t('cancelBooking')}</button></div></DialogContent></Dialog>
 </>;
}
function TouristHelp(){
 const{t,state,reload,busy}=useGuide();const[open,setOpen]=useState(false);
 return <><PageTitle title="help" text="travelerHelpText" action={<button className="button primary" onClick={()=>setOpen(true)}><Send size={18}/>{t('askSupport')}</button>}/><div className="section-title"><h2 className="standalone-heading">{t('myTickets')}</h2><button disabled={busy} className="button small" onClick={()=>void reload()}><RefreshCw size={16}/>{t('refresh')}</button></div>{state.feedback?.length?<div className="ticket-grid">{state.feedback.map(ticket=><TicketCard key={ticket.id} ticket={ticket}/>)}</div>:<section className="panel"><Empty title="noTickets" action={<button className="button" onClick={()=>setOpen(true)}>{t('askSupport')}</button>}/></section>}{open&&<FeedbackForm kind="help" onClose={()=>setOpen(false)}/>}</>;
}
function Exchange({open,close}:{open:boolean;close:()=>void}){const{t,lang}=useGuide();const[amount,setAmount]=useState(1000);const[data,setData]=useState<{rates:Record<string,number>;updated:string}|null>(null);const[error,setError]=useState(false);useEffect(()=>{if(open&&!data){setError(false);fetch('/api/rates').then(async r=>{if(!r.ok)throw new Error();setData(await r.json())}).catch(()=>setError(true))}},[open]);return <Dialog open={open} onOpenChange={v=>!v&&close()}><DialogContent><DialogHeader><DialogTitle>{t('exchange')}</DialogTitle><DialogDescription>{t('referenceRates')}</DialogDescription></DialogHeader><Field label={t('amount')+' · TRY'}><Input type="number" min={0} value={amount} onChange={e=>setAmount(Number(e.target.value))}/></Field>{data?<><div className="exchange-list">{['USD','EUR','RUB','GBP','SAR','IQD'].map(c=><div key={c}><span>{c}</span><b>{data.rates[c]?new Intl.NumberFormat(locale[lang],{maximumFractionDigits:2}).format(amount*data.rates[c]):'—'}</b></div>)}</div><small>{t('rateDate')}: {new Date(data.updated).toLocaleDateString(locale[lang])}</small><a href="https://www.exchangerate-api.com" target="_blank" rel="noreferrer" className="text-button">Rates By Exchange Rate API</a></>:<p>{t(error?'rates_unavailable':'loading')}</p>}</DialogContent></Dialog>}
